// Package stats. stats_test - unit tests for the descriptive statistics, the
// Mann-Whitney U test and the geometric mean, including golden p-values generated by
// SciPy (see scripts/gen-utest-vectors.py).
package stats

import (
	"encoding/json"
	"errors"
	"math"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// ---------------------------------------------- Types ----------------------------------------- //

// goldenVector is one entry of the fixture.
type goldenVector struct {
	// Name identifies the vector in failure output.
	Name string `json:"name"`
	// Method is the expected computation path ("exact" or "normal").
	Method string `json:"method"`
	// A and B are the two samples.
	A []float64 `json:"a"`
	// B is the second sample.
	B []float64 `json:"b"`
	// U is the expected U statistic.
	U float64 `json:"u"`
	// P is the expected two-sided p-value.
	P float64 `json:"p"`
}

// vectorPayload is the fixture document.
type vectorPayload struct {
	// Tolerance is the absolute tolerance applied to p-values.
	Tolerance float64 `json:"tolerance"`
	// Vectors are the golden cases.
	Vectors []goldenVector `json:"vectors"`
}

// vectorFile is the shared golden fixture, also replayed against the browser-side
// implementation by scripts/test-compare.mjs.
const vectorFile = "utest_vectors.json"

// ----------------------------------------- Public API ----------------------------------------- //

// TestSummarize covers the descriptive statistics, including the zero-median case
// where a relative spread would be undefined.
func TestSummarize(t *testing.T) {
	cases := []struct {
		name   string
		values []float64
		median float64
		min    float64
		max    float64
		spread float64
	}{
		{name: "odd count", values: []float64{3, 1, 2}, median: 2, min: 1, max: 3, spread: 0.5},
		{name: "even count averages the middle", values: []float64{1, 2, 3, 4}, median: 2.5, min: 1, max: 4, spread: 0.6},
		{name: "single value", values: []float64{42}, median: 42, min: 42, max: 42, spread: 0},
		{name: "zero median has no relative spread", values: []float64{0, 0, 0}, median: 0, min: 0, max: 0, spread: 0},
	}
	for _, testCase := range cases {
		t.Run(testCase.name, func(t *testing.T) {
			summary, err := Summarize(testCase.values)
			if err != nil {
				t.Fatalf("Summarize: %v", err)
			}
			if summary.Median != testCase.median {
				t.Errorf("median = %v, want %v", summary.Median, testCase.median)
			}
			if summary.Min != testCase.min || summary.Max != testCase.max {
				t.Errorf("min/max = %v/%v, want %v/%v", summary.Min, summary.Max, testCase.min, testCase.max)
			}
			if summary.N != len(testCase.values) {
				t.Errorf("n = %d, want %d", summary.N, len(testCase.values))
			}
			if math.Abs(summary.Spread-testCase.spread) > 1e-9 {
				t.Errorf("spread = %v, want %v", summary.Spread, testCase.spread)
			}
		})
	}
}

// TestSummarizeEmpty reports an error rather than inventing zeroes.
func TestSummarizeEmpty(t *testing.T) {
	if _, err := Summarize(nil); !errors.Is(err, ErrEmptyInput) {
		t.Fatalf("Summarize(nil) error = %v, want ErrEmptyInput", err)
	}
}

// TestSummarizeDoesNotReorderTheInput protects callers that keep observation order.
func TestSummarizeDoesNotReorderTheInput(t *testing.T) {
	values := []float64{5, 1, 4, 2, 3}
	if _, err := Summarize(values); err != nil {
		t.Fatalf("Summarize: %v", err)
	}
	want := []float64{5, 1, 4, 2, 3}
	for index := range want {
		if values[index] != want[index] {
			t.Fatalf("input was reordered: %v, want %v", values, want)
		}
	}
}

// TestMannWhitneyGoldenVectors checks the test against SciPy-produced p-values.
func TestMannWhitneyGoldenVectors(t *testing.T) {
	payload := loadVectors(t)
	if len(payload.Vectors) == 0 {
		t.Fatal("fixture contains no vectors")
	}
	for _, vector := range payload.Vectors {
		t.Run(vector.Name, func(t *testing.T) {
			result, err := MannWhitneyU(vector.A, vector.B)
			if err != nil {
				t.Fatalf("MannWhitneyU: %v", err)
			}
			if math.Abs(result.U-vector.U) > 1e-9 {
				t.Errorf("U = %v, want %v", result.U, vector.U)
			}
			if math.Abs(result.P-vector.P) > payload.Tolerance {
				t.Errorf("p = %.12f, want %.12f (tolerance %g)", result.P, vector.P, payload.Tolerance)
			}
			if result.Method != vector.Method {
				t.Errorf("method = %q, want %q", result.Method, vector.Method)
			}
		})
	}
}

// TestMannWhitneyInsufficientSamples pins the rule that fewer than four samples per
// side can never reach significance, so the test refuses instead of returning a
// misleading number.
func TestMannWhitneyInsufficientSamples(t *testing.T) {
	_, err := MannWhitneyU([]float64{1, 2, 3}, []float64{4, 5, 6})
	var insufficient *InsufficientSamplesError
	if !errors.As(err, &insufficient) {
		t.Fatalf("error = %v, want InsufficientSamplesError", err)
	}
	if insufficient.MinRequired != MinSamplesForSignificance {
		t.Errorf("MinRequired = %d, want %d", insufficient.MinRequired, MinSamplesForSignificance)
	}
	if message := err.Error(); !strings.Contains(message, "re-run with --count") {
		t.Errorf("error message %q does not tell the user what to do", message)
	}
}

// TestMannWhitneyExactBoundaries checks the smallest sample counts where
// significance becomes reachable, which is the precise reason for the rule.
func TestMannWhitneyExactBoundaries(t *testing.T) {
	separated := mannWhitneyUFor(t, []float64{1, 2, 3, 4}, []float64{5, 6, 7, 8})
	if separated.P > 0.05 {
		t.Errorf("four separated samples: p = %v, want <= 0.05", separated.P)
	}
	if separated.Method != MethodExact {
		t.Errorf("method = %q, want %q", separated.Method, MethodExact)
	}
}

// TestMannWhitneyTiesUseNormalPath checks that ties switch the computation to the
// tie-corrected normal approximation, even at small sample counts.
func TestMannWhitneyTiesUseNormalPath(t *testing.T) {
	result := mannWhitneyUFor(t, []float64{1, 1, 2, 2, 3, 3.5}, []float64{1, 2, 2.5, 3, 3.5, 4})
	if result.Method != MethodNormal {
		t.Fatalf("method = %q, want %q", result.Method, MethodNormal)
	}
	if result.P < 0 || result.P > 1 {
		t.Fatalf("p = %v, want a probability", result.P)
	}
}

// TestMannWhitneySymmetry checks that swapping the samples yields the same p-value:
// the test must not favour a side.
func TestMannWhitneySymmetry(t *testing.T) {
	left := []float64{1, 4, 9, 16, 25, 36, 49, 64}
	right := []float64{2, 3, 10, 15, 26, 35, 50, 63}
	forward := mannWhitneyUFor(t, left, right)
	backward := mannWhitneyUFor(t, right, left)
	if math.Abs(forward.P-backward.P) > 1e-12 {
		t.Errorf("p is not symmetric: %v vs %v", forward.P, backward.P)
	}
	if math.Abs(forward.U-backward.U) > 1e-9 {
		t.Errorf("U is not symmetric: %v vs %v", forward.U, backward.U)
	}
}

// TestGeomeanExcludesNonPositiveValues covers the "0 allocs/op" case: a zero or
// negative value has no logarithm, so it is excluded and reported in the count.
func TestGeomeanExcludesNonPositiveValues(t *testing.T) {
	value, count := Geomean([]float64{2, 8, 0, -3})
	if count != 2 {
		t.Errorf("count = %d, want 2 (the zero and the negative are excluded)", count)
	}
	if math.Abs(value-4) > 1e-12 {
		t.Errorf("geomean = %v, want 4", value)
	}
	if value, count := Geomean([]float64{0, 0}); count != 0 || value != 0 {
		t.Errorf("all-zero geomean = (%v, %d), want (0, 0)", value, count)
	}
}

// TestGeomeanOfRatiosMatchesManualComputation keeps the aggregate honest: the
// geomean of ratios is the product of the ratios raised to one over n.
func TestGeomeanOfRatiosMatchesManualComputation(t *testing.T) {
	value, count := Geomean([]float64{0.5, 2})
	if count != 2 {
		t.Fatalf("count = %d, want 2", count)
	}
	if math.Abs(value-1) > 1e-12 {
		t.Errorf("geomean = %v, want 1", value)
	}
}

// TestPercentChangeUndefinedOnZeroBase pins the zero-baseline rule.
func TestPercentChangeUndefinedOnZeroBase(t *testing.T) {
	if _, defined := PercentChange(0, 5); defined {
		t.Error("PercentChange(0, 5) reported a defined change, want undefined")
	}
	if value, defined := PercentChange(4, 5); !defined || math.Abs(value-25) > 1e-12 {
		t.Errorf("PercentChange(4, 5) = (%v, %v), want (25, true)", value, defined)
	}
}

// TestRelativeChangeReturnsZeroWhenUndefined keeps the renderer helper predictable.
func TestRelativeChangeReturnsZeroWhenUndefined(t *testing.T) {
	if value := RelativeChange(0, 7); value != 0 {
		t.Errorf("RelativeChange(0, 7) = %v, want 0", value)
	}
}

// -------------------------------------- Internal Helpers -------------------------------------- //

// loadVectors reads the shared golden fixture from the repository root.
func loadVectors(t *testing.T) vectorPayload {
	t.Helper()
	path := repoFile(t, filepath.Join("testdata", vectorFile))
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	var payload vectorPayload
	if err := json.Unmarshal(content, &payload); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	if payload.Tolerance <= 0 {
		t.Fatalf("%s has no tolerance", path)
	}
	return payload
}

// repoFile resolves a path relative to the repository root, so tests work no matter
// which package directory they run from.
func repoFile(t *testing.T, relative string) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatalf("getwd: %v", err)
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, relative)
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			t.Fatalf("go.mod not found above %s", relative)
		}
		dir = parent
	}
}

// mannWhitneyUFor runs the test and fails the test on error.
func mannWhitneyUFor(t *testing.T, a, b []float64) UTESTResult {
	t.Helper()
	result, err := MannWhitneyU(a, b)
	if err != nil {
		t.Fatalf("MannWhitneyU: %v", err)
	}
	return result
}
